"""Create a small, hand-authored V12 instruction-following pilot dataset.
Run: python -m training.v12.build_pilot
No network, GPU, or pretrained models needed.
"""
import argparse, json, pathlib, random

SCENES = [
('The Glass Orchard','fantasy','Mira, Sol','An orchard of glass trees','Mira and Sol retrieve a silver seed','The branches ring whenever someone lies','Mira admits she hid the map, and the trees open a path', '''Mira held the lantern beneath a tree whose transparent leaves chimed in the wind. Sol pointed to a silver seed suspended above them. "You said the map brought us here," he whispered. Mira reached for the branch, but the whole orchard rang sharply, and the seed drew farther away. She looked at Sol instead. "I hid the map because I was afraid you would leave without me." The ringing stopped. A narrow path opened between the glass trunks, and the seed fell softly into Sol's waiting hand.'''),
('Signal at Low Tide','science fiction','Nia, Tomas','A flooded communications tower','Restore a distress beacon before the tide rises','The backup battery has only one charge','They send the coordinates but sacrifice the tower lights', '''Water climbed the stairs of the communications tower as Nia stripped the casing from the transmitter. Tomas held the last dry battery above his head. "One pulse," he said. "After that, no lights." Nia checked the distress coordinates twice. The beacon flashed once across the gray bay, carrying their position to the rescue ships. Every lamp in the tower went dark. Tomas gripped the railing while the tide surged below them. In the distance, a ship answered with three brief flashes.'''),
('The Unsent Letter','literary fiction','Elena, Ruth','A quiet railway station','Elena must decide whether to give Ruth a letter','The train is about to depart','Elena reads one honest sentence aloud and stays', '''Elena folded the letter until its edges turned soft. Ruth waited beneath the station clock, her suitcase resting against her ankle. The departure bell sounded. Elena could have handed over the paper and watched the train carry the difficult words away. Instead she unfolded it. "I was angry because I thought you had forgotten me," she read. Ruth set down the suitcase. The doors closed without her. For a moment neither spoke, but Elena no longer needed the letter to do the talking.'''),
('The Salt Compass','adventure','Ivo, Sen','A desert caravan route','Find the hidden spring before their water runs out','Their compass points toward a salt cliff','They follow the shadow of the cliff and find water', '''By noon the last waterskin held only a mouthful. Ivo shook the compass; its needle still pointed straight at the white salt cliff. Sen studied the cliff's shadow stretching over the sand. "The needle isn't pointing at the rock," she said. "It's pointing beneath it." They walked along the shadow until the ground grew cool. Ivo dug with both hands and uncovered damp clay. A thin stream seeped into the hollow. Sen laughed, then filled the waterskin before either of them drank.'''),
('A Door for Winter','cozy fantasy','Pella, Bram','A village bakery during a snowstorm','Shelter stranded travelers','The bakery has almost no firewood','They share heat from the bread ovens and open the doors', '''Snow buried the bakery steps before dusk. Pella counted three logs beside the stove while Bram watched travelers gather outside the frosted window. "We can't warm everyone," he said. Pella opened the oven doors after the final loaves came out. Warm air rolled into the shop, carrying the smell of rye. Bram moved the benches close together and unlatched the front door. The travelers entered shaking snow from their coats. By morning the logs were gone, but the room had stayed warm with bodies, bread, and conversation.'''),
('The Museum Key','mystery','Ada, Finn','A closed maritime museum','Discover who moved a missing ship log','The display case is locked from inside','They find the log hidden beneath a repaired floorboard', '''Ada examined the empty display case while Finn tested its brass lock. The key had not been used; dust still lay across the keyhole. Yet the ship's log was gone. A fresh line of varnish caught Ada's eye beside the wall. Finn knelt and lifted a loose floorboard with his pocketknife. Beneath it rested the log, wrapped in a conservator's cloth. "Someone hid it to keep it dry," Ada said, seeing the leak spreading from the ceiling. The mystery was smaller than theft, but no less urgent.'''),
('The Bridge Keeper','fantasy','Korin, Vale','An ancient bridge over a ravine','Cross before sunrise','The bridge demands a memory as toll','Korin offers a treasured memory and Vale records it for him', '''The bridge keeper held out a palm of pale stone. "A memory," it said, "or turn back." Sunrise already touched the far peaks. Korin closed his eyes and gave up the sound of his mother's singing. He felt the loss like a sudden silence. The bridge unfolded across the ravine. Vale took his arm as they crossed. On the other side, she wrote every detail of the song Korin had once described in her notebook. He could not remember the tune, but he knew why she had written it down.'''),
('Last Shift','contemporary','Jules, Farah','A hospital cafeteria at dawn','Convince Farah to take a needed break','Farah refuses to leave her shift early','Jules offers to cover her tasks and Farah accepts', '''The cafeteria lights buzzed above the untouched tea. Farah stood with her pager in one hand and her coat in the other. "There is still work," she told Jules. He slid a sheet of paper across the table. He had listed every task she worried about, with his name beside each one. Farah read it twice. "You checked with the team?" Jules nodded. She finally sat down and took a sip of tea. Outside the windows, dawn reached the parking lot. For ten minutes, the pager stayed quiet.'''),
('The Tide Archive','science fiction','Rhea, Pax','An underwater research archive','Save a corrupted map of ocean currents','The archive computer is flooding','They copy the map onto a mechanical recorder', '''A red warning light washed over the archive as seawater seeped under the door. Rhea watched the current map break into squares on the damaged screen. Pax dragged a mechanical plotter from beneath the desk. "It only takes coordinates," he said. Rhea called out the surviving numbers while he punched them into the recorder. Water reached their boots. The plotter scratched a crooked but complete route onto waterproof film. They left the computer behind and climbed the emergency ladder with the map sealed inside Rhea's jacket.'''),
('The Bellmaker','historical fantasy','Oren, Lysa','A bell foundry beside a river','Cast a bell to warn the village of floods','A crack forms in the first casting','They recast the bell with metal donated by villagers', '''The first bell split as it cooled. Oren stared at the crack while the river rose beyond the foundry windows. Lysa carried the broken casting into the square and explained what had happened. One by one, villagers brought bent spoons, worn buckles, and brass ornaments. Oren melted the offerings together and poured a second bell before nightfall. When the river climbed the lower bank, Lysa struck it with an iron bar. Its clear note traveled over every roof, and lamps appeared in the uphill windows.'''),
('A Map of Moths','magical realism','Tali, Em','An attic full of old maps','Locate their grandmother’s lost garden','The maps change whenever the attic lamp goes out','They follow moths to a courtyard garden', '''Tali spread the maps across the attic floor. Every time Em switched off the lamp, the streets rearranged themselves. A pale moth settled on a blank corner of the oldest map. Then another landed beside it. Em opened the window, and the moths rose in a loose trail above the rooftops. The sisters followed them through two narrow lanes to a courtyard hidden behind a locked gate. Beyond the bars grew their grandmother's blue irises. Tali touched the rusted latch and smiled.'''),
('The Empty Seat','drama','Dev, Anika','A school auditorium before a concert','Persuade Anika to perform her solo','Anika fears making a mistake in front of the audience','She begins the piece after Dev joins her for the opening bars', '''The auditorium filled with murmurs while Anika stared at the empty piano bench. "I'll miss the first note," she told Dev. He pulled a second chair beside the piano. "Then I'll play the first four bars with you." When the curtain rose, his hands found the opening chords and hers followed. After the fourth bar, Dev lifted his fingers away. Anika kept playing. The next note was not perfect, but it was hers, and the room listened until the final chord faded.'''),
]

def main():
 p=argparse.ArgumentParser();p.add_argument('--output-dir',default='dataset/v12/pilot');a=p.parse_args();out=pathlib.Path(a.output_dir);out.mkdir(parents=True,exist_ok=True)
 for split, rows in [('train',SCENES[:8]),('val',SCENES[8:10]),('test',SCENES[10:])]:
  with (out/f'{split}.jsonl').open('w',encoding='utf-8') as f:
   for title,genre,characters,setting,objective,obstacle,outcome,story in rows:
    rec={'title':title,'genres':[genre],'characters':[s.strip() for s in characters.split(',')],'setting':setting,'objective':objective,'obstacle':obstacle,'outcome':outcome,'premise':f'{objective}. {obstacle}. {outcome}.','story':story.strip(),'review_status':'AUTHOR_WRITTEN_PILOT','source_family':title}
    f.write(json.dumps(rec,ensure_ascii=False)+'\n')
 print('Created 8 train / 2 val / 2 test hand-authored pilot examples in',out)
 print('Pilot is for format checks and tiny overfit experiments, NOT full V12 training.')
if __name__=='__main__':main()
